// Generate unique IDs and add missing fields
const processed = mammals.map((m, i) => {
  const id = m.name.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)/g, '');
  return {
    id,
    name: m.name,
    emoji: m.emoji,
    category: "mammal",
    habitat: m.habitat,
    diet: m.diet,
    lifespan: m.lifespan,
    weight: m.weight,
    speed: m.speed,
    length: m.length,
    conservation: m.conservation,
    funFact: m.funFact,
    description: m.description,
    region: m.region,
    class: "Mammalia",
    order: m.order,
    family: m.family
  };
});

// Deduplicate by id
const seen = new Set();
const unique = [];
for (const m of processed) {
  if (!seen.has(m.id)) {
    seen.add(m.id);
    unique.push(m);
  }
}

// Write the file
const outputPath = path.join(__dirname, 'data', '01-mammals.json');
fs.writeFileSync(outputPath, JSON.stringify(unique, null, 2), 'utf8');
console.log(`Generated ${unique.length} mammals to ${outputPath}`);
